#!/bin/bash echo -e "


Hi $LOGNAME 😃, What's up? " echo "1. Edit espanso config" echo "2. Edit bash aliases" echo "3. Midiverse!" echo "4. Watch France info" echo "5. coucou" echo "6. ❗Edit this teleport script!" echo "" echo "" echo "" echo "" read number case $number in 1) CONFIG=$(espanso path | awk '/Config:/ {print $2}') echo -e "Available match files:
$(ls $CONFIG/match)" code "$CONFIG/match" ;; 2) # Check if .bash_aliases file exists, if not create it if [ ! -f "$HOME/.bash_aliases" ]; then touch "$HOME/.bash_aliases" echo ".bash_aliases file created in $HOME" fi # Open the .bash_aliases file in VScode code "$HOME/.bash_aliases" ;; 3) xdg-open /media/ron/Ronzz_Core/nextCloudSync/mindiverse ;; 4) # Open the crashcourse CS playlist in Firefox xdg-open https://www.youtube.com/franceinfo ;; 5) cd "/media/ron/Ronzz_Core/nextCloudSync/mindiverse-life/coucou/coucou" eval $(poetry env activate) python3 main.py ;; 6) # Open the teleport script in VScode code "$(realpath "$0")" ;; *) echo "You did not select a valid number!!" ;; esac

CircuiTikz Bibliothèque LaTeX Un outil FOSS développé et maintenu par 4 universitaires européens : Massimo Redaelli (Italie, initiateur du projet) Deux Stefans : Stefan Lindner et Stefan Erhard (Allemagne, mainteneurs) Romano Giannetti (Espagne, professeur d’électronique) basée sur Tikz Installation and setup Normalement, la bibliothèque est déjà pré-installé en TexLive/MikTex Il ne faut que simplement l'activer : \usepackage[european, straightvoltage]{circuitikz} european, straightvoltage rassurent que les conventions européens sont correctement appliqués. Quelques bibliothèques supplémentaires peuvent être utiles : \usepackage{siunitx} % pour afficher les chiffres et unités correctement \usetikzlibrary{babel} % localisation française compatible avec tikz En sommaire, un préambule (header) complet rassemble : \documentclass[border = 1mm]{standalone} \usepackage[utf8]{inputenc} \usepackage{siunitx} \usepackage[european, straightvoltages, RPvoltages]{circuitikz} \usetikzlibrary{babel} Démarrez La grillage est utile en débuttant :  egin{circuitikz} \draw [help lines, gray, thin] (-5,-5) grid (5,5) [step=0.5]; % retour à la source \end{circuitikz} Un simple circuit :  egin{circuitikz} \draw [help lines, gray, thin] (5,-5) grid (5,5) [step=0.5]; % retour à la source \draw (0,0) to [vsource] (4,0); % source de pouvoir \draw (4,0) -- ++ (0,4); % (coordinate origin) --++ (vector) \draw (4,4) to [R] (0,4); % resistance \draw (0,4) -- (0,0); % (position d'origin) -- (position de fin) \end{circuitikz} Il est possible de dessiner plusieurs éléments sur la même ligne.  egin{circuitikz} \draw [help lines, gray, thin] (-5,-5) grid (5,5) [step=0.5]; % retour à la source \draw (0,0) to [vsource] (4,0) to[lamp] (4,4) to [R] (0,4) -- (0,0); \end{circuitikz} Les éléments Quelques éléments fréquemment dessinés : \documentclass{article} \usepackage[utf8]{inputenc} \usepackage{siunitx} \usepackage[european, straightvoltages, RPvoltages]{circuitikz} \usetikzlibrary{babel} \usepackage[margin=2cm]{geometry}  egin{document}  egin{center}  egin{circuitikz}[scale=0.8, transform shape] \draw (0,0) to[battery] (0,3); \draw (3,0) to[battery2] (3,3); \draw (6,0) to[isource] (6,3); \draw (9,0) to[vsourcesin] (9,3); \draw (12,0) to[vsourcesquare] (12,3); % Notations below each source 
ode at (0,-0.5) {Batterie}; 
ode at (3,-0.5) {Batterie 2}; 
ode at (6,-0.5) {Source de courant}; 
ode at (9,-0.5) {Source sinusoïdale}; 
ode at (12,-0.5) {Source carrée}; % Deuxième ligne : résistances \draw (0,-3) to[R] (0,-6); \draw (3,-3) to[vR] (3,-6); \draw (6,-3) to[pR] (6,-6); \draw (9,-3) to[sR] (9,-6); \draw (12,-3) to[phR] (12,-6); \draw (15,-3) to[thR] (15,-6); % Notations sous chaque composant de la 2e ligne 
ode at (0,-6.5) {Résistance}; 
ode at (3,-6.5) {Résistance variable}; 
ode at (6,-6.5) {Potentiomètre}; 
ode at (9,-6.5) {Capteur résistif}; 
ode at (12,-6.5) {Photorésistance}; 
ode at (15,-6.5) {Thermirésistance}; \end{circuitikz} \end{center} \end{document} Plus des éléments utiles : Les références sont également disponible en PDF . Une réference des éléments compilé par Nicolas Le Boulaire, qui contient aussi les éléments moins fréquentés, se trouve sur developpez.com . Ressources Supplémentaires Manuel officiel
